import{_ as a,o as e,c as r,ag as d}from"./chunks/framework.DMXcdKmJ.js";const o="/induframe-docs/images/login/reset-admin-dialog.png",u=JSON.parse('{"title":"完成首次设置","description":"使用平台管理入口为默认组织管理员设置密码，再从公共入口登录工作台。","frontmatter":{"title":"完成首次设置","description":"使用平台管理入口为默认组织管理员设置密码，再从公共入口登录工作台。","status":"reviewed","kind":"how-to"},"headers":[],"relativePath":"zh/installation/first-setup.md","filePath":"zh/安装运维/完成首次设置.md"}'),i={name:"zh/installation/first-setup.md"};function h(n,t,l,s,c,p){return e(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="完成首次设置" tabindex="-1">完成首次设置 <a class="header-anchor" href="#完成首次设置" aria-label="Permalink to &quot;完成首次设置&quot;">​</a></h1><h2 id="目标" tabindex="-1">目标 <a class="header-anchor" href="#目标" aria-label="Permalink to &quot;目标&quot;">​</a></h2><p>为默认组织管理员设置可用密码，开放组织登录，并进入工作台。</p><h2 id="角色与环境前提" tabindex="-1">角色与环境前提 <a class="header-anchor" href="#角色与环境前提" aria-label="Permalink to &quot;角色与环境前提&quot;">​</a></h2><p>由平台超级管理员完成密码重置，随后由默认组织管理员验证登录。开始前应已完成<a href="/induframe-docs/zh/installation/install.html">安装中心</a>，取得终端给出的公共入口、管理入口，以及安装时设置的平台超级管理员账号和密码。</p><p>两个入口使用不同的账号。即使用户名都为 <code>admin</code>，也不能把安装时设置的平台密码当作组织管理员密码。区别见<a href="/induframe-docs/zh/concepts/access.html">入口与账号</a>。</p><p>本页用于全新安装。保留数据后重新安装的平台继续使用原有管理员账号，不需要重新进行首次设置。</p><h2 id="操作入口" tabindex="-1">操作入口 <a class="header-anchor" href="#操作入口" aria-label="Permalink to &quot;操作入口&quot;">​</a></h2><p>先在能访问服务器管理网络的浏览器中，打开安装终端给出的<strong>管理入口</strong>。地址包含管理端口和 <code>/admin/</code>，页面标题为“平台管理员登录”。不要从公共入口开始设置。</p><h2 id="设置步骤与字段" tabindex="-1">设置步骤与字段 <a class="header-anchor" href="#设置步骤与字段" aria-label="Permalink to &quot;设置步骤与字段&quot;">​</a></h2><h3 id="_1-登录平台管理入口" tabindex="-1">1. 登录平台管理入口 <a class="header-anchor" href="#_1-登录平台管理入口" aria-label="Permalink to &quot;1. 登录平台管理入口&quot;">​</a></h3><p>填写以下字段，然后点击“登录”。</p><table tabindex="0"><thead><tr><th>字段</th><th>填写内容</th></tr></thead><tbody><tr><td>账号</td><td>安装时设置的平台超级管理员用户名，默认 <code>admin</code></td></tr><tr><td>密码</td><td>安装时自行设置的平台超级管理员密码</td></tr></tbody></table><p>正常全新安装无需再次修改平台密码。登录后进入“平台管理”，打开“组织管理”。</p><h3 id="_2-找到默认组织" tabindex="-1">2. 找到默认组织 <a class="header-anchor" href="#_2-找到默认组织" aria-label="Permalink to &quot;2. 找到默认组织&quot;">​</a></h3><p>在“组织管理”列表中找到名称为 <strong>InduFrame</strong> 的组织，其下方标有 <code>induframe · 默认组织</code>。查看这一行的“管理员”列并记下实际用户名，默认通常为 <code>admin</code>。</p><p>页面首次安全设置提示会说明需要重置默认组织管理员密码。系统生成的默认组织管理员初始密码不作为可供人工登录的密码使用，必须先完成下一步。</p><h3 id="_3-重置组织管理员密码" tabindex="-1">3. 重置组织管理员密码 <a class="header-anchor" href="#_3-重置组织管理员密码" aria-label="Permalink to &quot;3. 重置组织管理员密码&quot;">​</a></h3><p>点击默认组织这一行的“重置管理员密码”。在同名对话框中核对并填写以下字段。</p><p><img src="'+o+'" alt="重置管理员密码对话框，显示只读管理员用户名、新密码、确认密码与重置密码按钮"></p><p><em>图：默认组织的密码重置对话框。管理员用户名和空密码字段仅作界面说明。</em></p><table tabindex="0"><thead><tr><th>字段</th><th>操作</th></tr></thead><tbody><tr><td>管理员用户名</td><td>只读，确认与组织列表中的管理员一致</td></tr><tr><td>新密码</td><td>设置该组织管理员今后使用的密码</td></tr><tr><td>确认密码</td><td>再次输入同一密码</td></tr></tbody></table><p>建议为组织管理员设置 8–72 个英文字母、数字或半角符号组成的密码，两次输入相同，不能只填空格。完整长度限制见<a href="/induframe-docs/zh/reference/install-options.html#账号与密码">安装参数中的账号与密码</a>。不要把这组密码和安装时的平台超级管理员密码混淆。</p><p>点击对话框中的 <strong>“重置密码”</strong>。成功后会提示“管理员密码已重置”，默认组织完成设置，公共入口自动开放。首次安全设置提示区可能随设置完成而收起。</p><h3 id="_4-从公共入口登录默认组织" tabindex="-1">4. 从公共入口登录默认组织 <a class="header-anchor" href="#_4-从公共入口登录默认组织" aria-label="Permalink to &quot;4. 从公共入口登录默认组织&quot;">​</a></h3><p>打开安装终端给出的<strong>公共入口</strong>，确认页面标题为“登录工作台”。若使用自签名证书，先由维护人员核对访问地址和证书，并完成浏览器信任处理。</p><table tabindex="0"><thead><tr><th>字段</th><th>填写内容</th></tr></thead><tbody><tr><td>选择组织</td><td>出现此字段时选择“InduFrame”；只有一个可登录组织时会自动选中，不显示选择框</td></tr><tr><td>账号</td><td>默认组织列表中显示的管理员用户名</td></tr><tr><td>密码</td><td>刚刚重置的组织管理员密码</td></tr></tbody></table><p>点击“登录”。重置成功后，该组织管理员可以使用新密码直接进入工作台，无需再改一次密码。</p><h2 id="成功确认" tabindex="-1">成功确认 <a class="header-anchor" href="#成功确认" aria-label="Permalink to &quot;成功确认&quot;">​</a></h2><ul><li>平台超级管理员可以进入“组织管理”。</li><li>重置默认组织管理员密码后，出现“管理员密码已重置”提示。</li><li>公共入口不再显示“租户入口尚未开放”，默认组织管理员能使用新密码进入工作台。</li></ul><h2 id="未能完成时" tabindex="-1">未能完成时 <a class="header-anchor" href="#未能完成时" aria-label="Permalink to &quot;未能完成时&quot;">​</a></h2><p>如果公共入口仍显示“租户入口尚未开放”，返回管理入口核对是否重置了标有“默认组织”的 InduFrame 组织，并确认重置操作成功后刷新公共登录页。</p><p>如果密码重置未成功，检查两次输入是否一致、是否全为空白、是否超过字节长度限制。管理员用户名为只读字段，不要尝试在该对话框中更换账号。</p><p>如果不能登录，先核对入口、组织和账号用途。仍有问题，记录页面标题、操作与提示，交给平台维护人员；不要用重新安装代替密码处理。其他现象见<a href="/induframe-docs/zh/installation/troubleshooting.html">安装常见问题</a>。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><p>继续<a href="/induframe-docs/zh/installation/verify.html">确认安装成功</a>，检查工作台访问、页面刷新和退出登录。日常登录操作见<a href="/induframe-docs/zh/guide/login.html">登录与退出</a>。</p>',36)])])}const b=a(i,[["render",h]]);export{u as __pageData,b as default};
